-- composition of rule kernels Coroutines x OrderBySubq (sqlite), template graft_exists
CREATE VIEW n1 AS SELECT 7 AS c0 UNION SELECT 1 AS c0;
WITH cte1 AS MATERIALIZED (SELECT MIN (CAST('abc' AS TEXT), CAST('ß' AS TEXT)) AS c0 FROM (SELECT FORMAT ('%s|%s', '{"k": 1, "a": [1, 2]}', '{}') AS c0, '2000-01-01 00:00:00' AS c1 FROM n1 AS a1 GROUP BY a1.c0) AS a2 WHERE TRUE GROUP BY a2.c1) SELECT 7 AS c0, (-42) AS c1, CAST(100 AS INTEGER) AS c2 FROM (SELECT * FROM cte1 WHERE EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT FALSE AS c0, CAST('ß' AS TEXT) AS c1 UNION ALL SELECT TRUE AS c0, CAST('x%' AS TEXT) AS c1 FROM rc AS a1) AS kb) OR NOT EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT FALSE AS c0, CAST('ß' AS TEXT) AS c1 UNION ALL SELECT TRUE AS c0, CAST('x%' AS TEXT) AS c1 FROM rc AS a1) AS kb)) AS a3 WHERE FALSE;
